<template><div class="pay-page"><div class="amount"><div class="label">支付金额</div><div class="money">¥{{ order.total_amount || '0.00' }}</div></div><div class="order-info"><div class="row"><span>订单号</span><span>{{ order.order_no }}</span></div><div class="row"><span>商品</span><span>{{ order.goods_name || '多件商品' }}</span></div></div><div class="pay-methods"><div class="title">选择支付方式</div><el-radio-group v-model="payMethod"><el-radio label="wechat">微信支付</el-radio><el-radio label="alipay">支付宝</el-radio><el-radio label="balance">余额支付</el-radio></el-radio-group></div><div class="footer"><el-button type="primary" @click="doPay" :loading="loading" style="width:100%">确认支付</el-button></div></div></template><script setup>import{ref,onMounted}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage}from'element-plus';import request from'@/utils/request';const route=useRoute();const router=useRouter();const order=ref({});const payMethod=ref('wechat');const loading=ref(false);const doPay=async()=>{loading.value=true;try{await request({url:`/pay/${route.params.orderNo}`,method:'post',data:{pay_method:payMethod.value}});ElMessage.success('支付成功');router.replace('/orders')}catch(e){ElMessage.error('支付失败')}finally{loading.value=false}};onMounted(async()=>{const res=await request({url:`/orders/by-no/${route.params.orderNo}`});order.value=res.data||{}})</script><style scoped>.pay-page{padding:20px}.amount{text-align:center;padding:30px 0}.amount .label{font-size:14px;color:#909399}.amount .money{font-size:36px;font-weight:bold;color:#f56c6c;margin-top:10px}.order-info{background:#fff;border-radius:8px;padding:15px;margin-bottom:20px}.order-info .row{display:flex;justify-content:space-between;padding:8px 0;font-size:14px}.pay-methods{background:#fff;border-radius:8px;padding:15px}.pay-methods .title{font-size:14px;font-weight:500;margin-bottom:15px}.footer{position:fixed;bottom:0;left:0;right:0;padding:15px 20px;background:#fff;border-top:1px solid #eee}</style>
